"""Build reviewable tables/plots without pooling correlated paired executions."""
from baseline import *
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import Rectangle,Circle

def main():
 out=ROOT/'results';rows=json.load(open(out/'results.json'));manifest=json.load(open(out/'manifest.json'))
 groups=[('nominal',-1.)]+[('chance',b) for b in BUDGETS]
 summary=[]
 for method,b in groups:
  rr=[r for r in rows if r['method']==method and r['budget']==b]
  summary.append(dict(method=method,budget=b,plans=len(rr),nominal_healthy=sum(not r['nominal']['failure'] for r in rr),surrogate_accepted=sum(r['surrogate_accepted'] for r in rr),audit_accepted=sum(r['audit_accepted'] for r in rr),failure_rate=float(np.mean([r['failure_rate'] for r in rr])),collision_rate=sum(r['counts']['collision'] for r in rr)/sum(r['executions'] for r in rr),goal_failure_rate=sum(r['counts']['goal_failure'] for r in rr)/sum(r['executions'] for r in rr),mean_cost=float(np.mean([r['cost_mean'] for r in rr])),sampling_batch_seconds=rr[0]['sampling_batch_seconds'],predicted_risk_min=min(r['predicted_risk'] for r in rr),predicted_risk_max=max(r['predicted_risk'] for r in rr)))
 json.dump(summary,open(out/'summary.json','w'),indent=2)
 e=gym.make('maze2d-large-v1').unwrapped;e.reset();ch=Chance(e,np.load(ROOT/'normalization.npz'))
 fig,axes=plt.subplots(3,4,figsize=(15,10),sharex=True,sharey=True)
 for col,(method,b) in enumerate(groups):
  for task in range(3):
   ax=axes[task,col];i=task*manifest['seeds'];r=next(r for r in rows if r['method']==method and r['budget']==b and r['task']==task and r['seed']==manifest['seed_base'])
   p=np.load(out/f'{method}_{b}_{i}_rollouts.npz')
   for center in ch.centers:ax.add_patch(Rectangle(center.numpy()[::-1]-.5,1.,1.,facecolor='.82',edgecolor='white',lw=.3))
   for key,color,style in [('mean','tab:orange','--'),('nominal','tab:blue','-'),('stochastic','tab:red','-')]:
    path=p[key];ax.plot(path[:,1],path[:,0],style,color=color,lw=1.1,label=key)
   goal=TASKS[task][1];start=TASKS[task][0];ax.add_patch(Circle(goal[::-1],.5,color='green',alpha=.15));ax.plot(*start[:2][::-1],'ko',ms=3)
   ax.set_aspect('equal',adjustable='box');ax.set_xlim(-.7,11.3);ax.set_ylim(8.3,-.7);ax.set_xlabel('qpos_y',fontsize=8);ax.set_ylabel('qpos_x ↓',fontsize=8);ax.set_title(f'{method} Δ={b if b>=0 else "—"}\ntask {task}; R={r["predicted_risk"]:.1f}; fail={r["failure_rate"]:.2f}',fontsize=9)
 axes[0,0].legend(fontsize=7,loc='lower left');fig.suptitle('Native maze2d-large-v1: familiar Diffuser orientation; complete boundary; equal physical aspect',fontsize=12)
 fig.tight_layout();fig.savefig(out/'trajectories.png',dpi=150);plt.close(fig)
 lines=['# Maze2D chance-guided diffusion experiment','', '## Outcome','', '**This bounded experiment did not demonstrate budget-compliant safe generation.** The checkpoint must pass nominal execution health before risk improvements can be interpreted. No universal safety guarantee is claimed.','', 'The source is slides 13–14 of `main.pptx`, inspected as the six extracted embedded PNGs in `slide_evidence/`.','', '## Map verification', '', 'The experiment and older RB Diffuser load the **exact same 9×12 LARGE_MAZE array**, verified against the installed D4RL registration, checkpoint dataset config, legacy loader and renderer, and every native wall geometry. It is not LARGE_MAZE_EVAL. Only the original image viewport cropped the outer walls; the native simulator, risk calculation, and hard execution audit included the full boundary throughout. The original figure made qpos_x horizontal and qpos_y vertical, with a cropped boundary; RB Diffuser instead plots qpos_y horizontally, qpos_x downward and normalizes both to a square. The corrected figure restores the familiar orientation and full boundary, while keeping equal physical aspect so circular goal regions remain circular. No trajectories or outcomes were regenerated. See `map_verification.json` and `map_verification.png`; the original is preserved as `trajectories_original_raw_axes.png`. The legacy bitmap adds +0.5 to normalized path coordinates; actual native wall centers in qpos coordinates are maze indices−0.2, which the corrected physical plot preserves.', '', '![Exact map comparison](map_verification.png)', '', '## Frozen execution and protocol','',f'Checkpoint: `{manifest["checkpoint"]}` (EMA, epoch {manifest["epoch"]}); SHA-256 `316e7e0449d36ed605e7d42d7d6a12fe3803b01b80037c5a268ff537aede8555`. Native D4RL `maze2d-large-v1`, MuJoCo contacts and walls retained. Direct generated actions are executed for 383 steps, once per full-trip plan; no tracker, replanning, retries or added obstacles.','',f'Exact initial state is reset after `env.reset`, removing reset randomness. After each native step, independently add N(0, {SIGMA}² I₂) to velocity. This explicit disturbance is the only execution uncertainty. Actions are clipped to [-1,1] and pre-step velocity to [-5,5], exactly as native. Terminal position must be within radius 0.5 of the goal; any native wall contact at signed contact distance <=0.002 is a trajectory failure. Every obstacle time, including terminal time, is audited.','',f'Tasks: `{TASKS}`. Held-out sampling seeds {manifest["seed_base"]}–{manifest["seed_base"]+manifest["seeds"]-1}; same initial and every denoising noise draw across methods/budgets. Each plan has {manifest["executions"]} independent stochastic executions, seeds {manifest["execution_seed_base"]} onward, paired across candidates. Final audit noise seeds differ from both pilot runs.','', '## Fidelity to slides','', 'At every one of 256 denoising steps: candidate normalized actions → physical bounded controls → mean native free-space rollout → local dynamics Jacobian → covariance → signed native-box constraint and circular goal linearizations → Gaussian CDF violation probabilities → their untruncated union sum → `softplus(10 * (risk_sum - Delta))` → PyTorch reverse-mode gradient. The DDPM posterior mean is shifted by `-posterior_variance * 0.002 * gradient`. This is score guidance with lambda*beta=0.002. The chain rule includes action normalization. Observations are still conditioned by the same pretrained joint model; energy depends on executed actions, not sampled state waypoints.','', 'No division by gamma, horizon, number of constraints, or gradient norm is performed. There is no risk-conditioned retraining, projection, CVaR, surrogate candidate filtering, or additional method. Actual control `u_t` is the current noisy diffusion action candidate, clipped only by the execution transition. The final DDPM step has zero posterior variance, hence zero guidance displacement. Energy is not evaluated on a secretly optimized/denoised reference.','', 'The native free transition is `v_next = (m*clip(v,-5,5) + 0.01*100*clip(u,-1,1))/(m+0.01)` and `p_next=p+0.01*v_next`, with m=4.188790204786391 and damping=1. Its position/velocity Jacobian includes the local velocity-clip derivative. The independent velocity impulse is added after this transition. Same-axis 2×2 covariance blocks are propagated exactly for this local free linearization; cross-axis covariance is zero.','', 'Signed Euclidean distance to each native box minus sphere radius 0.1 and contact margin 0.002 defines g>=0 as safe. Constraints use the actual native geometry offset relative to the moving body, not array-cell centers. A terminal goal signed distance is included. This adds terminal wall risk to the slides’ k=1…N−1 obstacle convention, a conservative indexing extension.','', 'Contact dynamics are deliberately not substituted by free dynamics in execution. The guidance rollout models the pre-contact native transition; once collision is predicted, Gaussian/free-space linearization is unreliable. Both the signed-distance and goal Gaussian probabilities are first-order approximations. Their sum is an approximate surrogate, not a mathematical bound on the nonlinear contact system. It is not clipped to 1 for acceptance or energy.','', '## Results','', '| Method / budget | Healthy, no-noise plans | Surrogate accepted | Audit accepted | Actual failure | Collision | Goal failure | Mean action cost | Batch generation s |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for r in summary:lines.append(f'| {r["method"]} / {r["budget"] if r["budget"]>=0 else "—"} | {r["nominal_healthy"]}/{r["plans"]} | {r["surrogate_accepted"]}/{r["plans"]} | {r["audit_accepted"]}/{r["plans"]} | {r["failure_rate"]:.3f} | {r["collision_rate"]:.3f} | {r["goal_failure_rate"]:.3f} | {r["mean_cost"]:.2f} | {r["sampling_batch_seconds"]:.2f} |')
 lines+=['', 'Rates in the overview are descriptive averages over the nine fixed plans per row; they are not pooled independent binomial estimates. Native action cost is sum of squared clipped controls; runtime is measured batch throughput on RTX4090, not single-plan latency. Per-plan runtime and path length are stored in `results.json`.','', '## Independent audit and calibration','', 'Each plan has a pointwise exact two-sided 95% Clopper–Pearson interval. Audit acceptance separately requires a one-sided exact upper bound <=Delta, with Bonferroni family alpha 0.05 over all 27 guided candidates, regardless of surrogate acceptance. No execution was used to revise its candidate. A surrogate rejection remains a rejection even if an audit happens to pass. False-safe rate among accepted candidates is undefined when none is accepted, rather than reported as zero.','', '| Method | Δ | Task | Seed | Surrogate union sum | Observed failures / n | Exact 95% failure CI | Healthy without noise |','|---|---:|---:|---:|---:|---:|---|---|']
 for r in rows:lines.append(f'| {r["method"]} | {r["budget"]} | {r["task"]} | {r["seed"]} | {r["predicted_risk"]:.4f} | {r["counts"]["failure"]}/{r["executions"]} | [{r["failure_exact_ci95"][0]:.4f}, {r["failure_exact_ci95"][1]:.4f}] | {not r["nominal"]["failure"]} |')
 lines+=['', '## Validation and limitations','', 'See `validation.json`: 100 random native free one-step comparisons (including both clipping operations), covariance versus 100,000 independently simulated noise paths, and a finite-difference check of the complete energy. See `check_sampler.log`: direct generated-action execution can be healthy for the legacy noise stream, but the deliberately held-out candidates expose poor model/action consistency. The custom sampler uses independent per-candidate CUDA generators and `randn`; legacy uses global RNG and `randn_like`, so equal integer seeds do not imply identical legacy sample paths. Nominal and chance methods here do share every noise draw.','', 'The original health probe and two disclosed pilots are preserved. Pilot seed100 used strength0.002 and 50 executions; a second pilot seed11 used strength0.02 and 30 executions, which did not improve quality. The final strength0.002, sigma0.005, dynamics, tasks, budgets and protocol were frozen before the held-out seeds21–23 comparison. No pilot candidates were selected into final results. Poor no-noise health precludes interpreting differences as evidence of robust safety improvement. Three tasks and three samples/task are a limited checkpoint assessment, not a broad benchmark.','', 'The linearized CDF can saturate for failed candidates, and softplus is almost linear when risk greatly exceeds all budgets. This can yield nearly identical guidance across budgets; the absence of budget sensitivity is an observed limitation, not proof that budgets are enforced. Union sums greater than 1 are legitimate sums of approximate marginals and signal rejection. No sub-budget calibration evidence is available when no candidate has such a prediction.','', '![Native trajectory comparison](trajectories.png)']
 (out/'REPORT.md').write_text('\n'.join(lines)+'\n')
 print(json.dumps(summary,indent=2))
if __name__=='__main__':main()
